const r="// 传统沙箱脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n// 额外注入：ElMessage\r\n\r\n// 页面初始化\r\nconsole.log('🔄 异步演示页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\n\r\n// 注册页面函数\r\nregisterFunction('refreshAllData', async function() {\r\n  try {\r\n    ElMessage.info('正在刷新数据...')\r\n    await $refreshData()\r\n    ElMessage.success('所有数据刷新成功！')\r\n    console.log('刷新后的数据:', $data())\r\n  } catch (error) {\r\n    ElMessage.error('刷新数据失败')\r\n    console.error('刷新失败:', error)\r\n  }\r\n});\r\n\r\nregisterFunction('refreshOrders', async function() {\r\n  try {\r\n    ElMessage.info('正在刷新订单数据...')\r\n    await $refreshData('recentOrders')\r\n    ElMessage.success('订单数据刷新成功！')\r\n    console.log('最新订单:', $data().recentOrders)\r\n  } catch (error) {\r\n    ElMessage.error('刷新订单数据失败')\r\n    console.error('刷新失败:', error)\r\n  }\r\n});\r\n";export{r as default};
